const { repositoryUrl, issuesUrl, publishedFileUrl, publishedUserscriptFileName } = require('./repository.cjs');

// Tampermonkey's own headers line up at this column; keeping it makes the
// generated file readable in the editor Tampermonkey shows on install.
const KEY_COLUMN_WIDTH = 13;

function metadataLine(key, value = '') {
    const paddedKey = `@${key}`.padEnd(KEY_COLUMN_WIDTH, ' ');
    return `// ${value ? `${paddedKey} ${value}` : paddedKey.trimEnd()}`;
}

// @updateURL is what makes a published script self-updating: Tampermonkey re-reads
// the metadata block at that address on its own schedule and pulls @downloadURL
// whenever @version is higher than the installed one. Bumping the version in
// userscript.json and pushing dist/ is therefore the entire release process.
function buildMetadataBlock(script) {
    const publishedFileName = publishedUserscriptFileName(script.id);
    const lines = [
        '// ==UserScript==',
        metadataLine('name', script.name),
        metadataLine('namespace', repositoryUrl()),
        metadataLine('version', script.version),
        metadataLine('description', script.description),
        metadataLine('author', script.author),
        ...script.matches.map((match) => metadataLine('match', match)),
        ...script.connects.map((connect) => metadataLine('connect', connect)),
        ...script.grants.map((grant) => metadataLine('grant', grant)),
        ...(script.noFrames ? [metadataLine('noframes')] : []),
        metadataLine('run-at', script.runAt),
        metadataLine('homepageURL', `${repositoryUrl()}/tree/main/${script.toolDirectoryPath}`),
        metadataLine('supportURL', issuesUrl()),
        metadataLine('updateURL', publishedFileUrl(publishedFileName)),
        metadataLine('downloadURL', publishedFileUrl(publishedFileName)),
        '// ==/UserScript==',
        `// Generated from ${script.toolDirectoryPath}/src by "npm run build". Do not edit this file.`,
        `// Installing from ${publishedFileUrl(publishedFileName)} lets Tampermonkey update it on its own.`
    ];
    return `${lines.join('\n')}\n`;
}

// Tampermonkey only reads the first metadata block, so a published file must not
// grow a second one through a stray source comment.
function countMetadataBlocks(userscriptText) {
    return userscriptText.split('\n').filter((line) => line.trim() === '// ==UserScript==').length;
}

module.exports = { buildMetadataBlock, countMetadataBlocks, metadataLine };
